            CHECK(pattern_intact(v));            /* value bytes not written */
            CHECK(rb_size(t) == 0);              /* tree unchanged */
            CHECK(rb_validate(t) == 0);          /* still a valid RB tree */
            CHECK(rb_find(t, "orphan") == NULL); /* key not present */
